from fastapi import FastAPI, Depends
from fastapi.security import OAuth2PasswordBearer, Security
from fastapi.openapi.utils import get_openapi

app = FastAPI()

oauth2_scheme = OAuth2PasswordBearer(
    tokenUrl="token",
    scopes={"me": "Read information about the current user.", "items": "Read items."}
)

def get_current_user_me(token: str = Security(oauth2_scheme, scopes=["me"])):
    return {"token": token}

def get_current_user_items(token: str = Security(oauth2_scheme, scopes=["items"])):
    return {"token": token}

@app.get("/me")
def read_me(user = Depends(get_current_user_me)):
    return user

@app.get("/items")
def read_items(user = Depends(get_current_user_items)):
    return user

if __name__ == "__main__":
    import json
    openapi_schema = get_openapi(app, title="Test App", version="1.0.0")
    print(json.dumps(openapi_schema, indent=2))

